import Foundationimport FirebaseDatabaseclass UserService {        static let shared = UserService()    private init() {}        private let databaseRef = Database.database().reference()        // Save user to Realtime Database    func createUser(user: User, completion: @escaping (Error?) -> Void) {        databaseRef            .child("users")            .child(user.uid)            .setValue(user.toDictionary()) { error, _ in                completion(error)            }    }        // Fetch user by UID (optional but useful)    func fetchUser(uid: String, completion: @escaping (User?) -> Void) {        databaseRef            .child("users")            .child(uid)            .observeSingleEvent(of: .value) { snapshot in                                guard let data = snapshot.value as? [String: Any] else {                    completion(nil)                    return                }                                let user = User(                    uid: uid,                    name: data["name"] as? String ?? "",                    email: data["email"] as? String ?? "",                    phone: data["phone"] as? String ?? "",                    userType: data["userType"] as? String ?? ""                )                                completion(user)            }    }    func updateUserType(uid: String, userType: String, completion: @escaping (Error?) -> Void) {        databaseRef            .child("users")            .child(uid)            .child("userType")            .setValue(userType) { error, _ in                completion(error)            }    }}